// === Tab: mySketch ===
let asciiChars = [
  "░", "▒", "▓", "█",
  "▄", "▀", "▌", "▐",
  "▖", "▗", "▘", "▙", "▚", "▛", "▜", "▝", "▞", "▟",
  "▁", "▂", "▃", "▄", "▅", "▆", "▇", "█",
  "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█",
  "─", "━", "│", "┃", "┌", "┐", "└", "┘",
  "├", "┤", "┬", "┴", "┼", "╳", "╱", "╲",
  "⣿", "⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯",
  "⠀", "⠁", "⠃", "⠇", "⠏", "⠟", "⠿", "⡿"
];

let colors = ['#484064', '#786B88', '#DFAF66', '#24212C', '#B79767',
              '#EDE1D6', '#C16359', '#38806B', '#719CA9', '#979189'];

let cols, rows;
let cellSize = 10;
let zOff = 0;

// padding (relative to canvas)
let padLeft, padRight, padTop, padBottom;

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(12);
  textSize(cellSize);
  textAlign(CENTER, CENTER);
  textFont("Courier New, Lucida Console, monospace");
  computeGrid();
  noiseDetail(5, 0.5);
}

function draw() {
  background(255);
  noStroke();

  let xStart = frameCount * 0.1;
  let yStart = frameCount * 0.1;

  for (let y = 0; y < rows; y++) {
    let yOff = y * 0.15 + yStart;
    for (let x = 0; x < cols; x++) {
      let xOff = x * 0.15 + xStart;
      let n = noise(xOff, yOff, zOff);

      // map to ASCII char
      let idxChar = floor(map(n, 0, 1, 0, asciiChars.length));
      idxChar = constrain(idxChar, 0, asciiChars.length - 1);

      // map to color
      let idxCol = floor(map(n, 0, 1, 0, colors.length));
      idxCol = constrain(idxCol, 0, colors.length - 1);

      let ch = asciiChars[idxChar];
      let c = colors[idxCol];

      fill(c);
      text(
        ch.toString(),
        padLeft + x * cellSize + cellSize / 2,
        padTop + y * cellSize + cellSize / 2
      );
    }
  }

  zOff += 0.02;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  computeGrid();
}

function computeGrid() {
  padLeft   = width * 0.15;
  padRight  = width * 0.15;
  padTop    = height * 0.15;
  padBottom = height * 0.15;

  let gridWidth = width - padLeft - padRight;
  let gridHeight = height - padTop - padBottom;

  cols = floor(gridWidth / cellSize);
  rows = floor(gridHeight / cellSize);
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
